params.fn:
function(){
  var loginVisible=!!document.querySelector('.login-container,[class*="login-mask"],.qrcode-img');
  var body=(document.body&&document.body.innerText)||'';
  if(body.indexOf('扫码登录')>=0)loginVisible=true;
  var profile=document.querySelector('a.link-wrapper[href*="/user/profile/"],.main-container .user a[href*="/user/profile/"]');
  return {logged_in:!!profile&&!loginVisible};
}

function(){
  var img=document.querySelector('.qrcode-img');
  if(!img){return {logged_in:false,error:'未找到二维码'};}
  var src=img.src||'';
  if(src.indexOf('base64,')<0){return {logged_in:false,error:'二维码 src 无效'};}
  return {logged_in:false,qrcode_data_url:src};
}
